#!/bin/bash
# separate-verifier@1 entry: restore the agent snapshot captured by the
# [[verifier.collect]] snapshot hook, then run the original grading
# script (tests/test-orig.sh) unmodified.
set -u
SNAP="/var/tmp/mimo-separate"
M="/var/lib/mimo"
CWD="/testbed"
V=/logs/verifier
mkdir -p "$V" "$M"
# Verifier-side probe: the marker must be present here (bundled tests).
{
echo "== marker in /tests ==";
grep -rl "TestWeightNegativeAndHighFix" /tests 2>/dev/null || echo "MARKER NOT FOUND IN /tests";
} > "$V/separate-probe.txt" 2>&1
test -f "$SNAP/base" || { echo "snapshot missing: $SNAP/base" >&2; exit 1; }
test -f "$SNAP/workspace.tgz" || { echo "snapshot missing: $SNAP/workspace.tgz" >&2; exit 1; }
cp "$SNAP/base" "$M/base"
if [ -f "$SNAP/git-hidden.tgz" ]; then
  rm -rf "$CWD/.git" "$M/git-hidden";
  tar -xzf "$SNAP/git-hidden.tgz" -C "$M";
fi
cd "$CWD"
find "$CWD" -mindepth 1 -maxdepth 1 ! -name .git -exec rm -rf {} +
tar -xzf "$SNAP/workspace.tgz" -C "$CWD"
exec /tests/test-orig.sh
